<?php
namespace Delnavazan\Platform\Core\Application;
use Delnavazan\Platform\Core\Infrastructure\Repository\{TeacherRepository,StudentRepository,InstrumentRepository,CourseRepository,EnrolmentRepository,TermRepository,LessonRepository,BaseRepository};
final class ArchiveService { private const MAP=['teacher'=>[TeacherRepository::class,'dzn_manage_teachers','inactive'],'student'=>[StudentRepository::class,'dzn_manage_students','inactive'],'instrument'=>[InstrumentRepository::class,'dzn_manage_courses','inactive'],'course'=>[CourseRepository::class,'dzn_manage_courses','inactive'],'enrolment'=>[EnrolmentRepository::class,'dzn_manage_enrolments','paused'],'term'=>[TermRepository::class,'dzn_manage_terms','draft'],'lesson'=>[LessonRepository::class,'dzn_manage_lessons',null]]; public function archive(string $type,int $id):void{[$repo,$cap]=$this->entry($type);if(!current_user_can($cap))throw new \RuntimeException('Unauthorized');$row=$repo->find($id);if(!$row||$row->status==='scheduled'||in_array($row->status,['completed','cancelled'],true))throw new \InvalidArgumentException('Archive conflict');$repo->archive($id,gmdate('Y-m-d H:i:s'),get_current_user_id()?:null);} public function restore(string $type,int $id):void{[$repo,$cap,$status]=$this->entry($type);if(!current_user_can($cap))throw new \RuntimeException('Unauthorized');$row=$repo->find($id);if(!$row||$row->status!=='archived')throw new \InvalidArgumentException('Record is not archived');if($type==='lesson')$status=$row->current_schedule_version_id?'scheduled':'draft';$repo->restore($id,$status,gmdate('Y-m-d H:i:s'),get_current_user_id()?:null);} private function entry(string $type):array{if(!isset(self::MAP[$type]))throw new \InvalidArgumentException('Unsupported archive type');[$class,$cap,$status]=self::MAP[$type];return[new $class,$cap,$status];} }
